export type TokenPath = keyof typeof cssVars;

export type TokenLayer = 'primitive' | 'semantic' | 'component';
export type TokenStatus = 'provisional' | 'unresolved' | 'retired';
export interface TokenOrigin {
  readonly status: 'provisional' | 'unresolved';
  readonly path: string;
}
/** status is the token's own (direct) flag; inheritedFrom lists the directly flagged tokens it references, directly or not. */
export interface TokenMeta {
  readonly layer: TokenLayer;
  readonly cssVar: string;
  readonly description?: string;
  readonly status?: TokenStatus;
  readonly inheritedFrom?: readonly TokenOrigin[];
  readonly source?: 'documented' | 'observed';
}

